<script setup lang="ts">import {ref,onMounted,onUnmounted} from 'vue';defineProps<{name:string;csrf?:string;canEdit?:boolean;superAdmin?:boolean}>();const emit=defineEmits(['profile']);const root=ref<HTMLDetailsElement|null>(null);function close(){if(root.value)root.value.open=false;}function outside(e:Event){if(!root.value?.contains(e.target as Node))close();}onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>document.removeEventListener('pointerdown',outside));</script><template><details ref="root" class="pms-account-menu" @keydown.esc="close"><summary aria-label="Account menu"><span class="pms-account-avatar">{{name.charAt(0)||'A'}}</span><span class="pms-account-online"></span></summary><div class="pms-account-dropdown"><strong>{{name}}</strong><small>{{superAdmin?'Super Admin':'PMS workspace'}}</small><button v-if="canEdit" type="button" @click="close();emit('profile')"><i aria-hidden="true" class="ti ti-user"></i>My profile</button><a href="/products"><i aria-hidden="true" class="ti ti-apps"></i>All products</a><a v-if="superAdmin" href="/admin"><i aria-hidden="true" class="ti ti-settings"></i>Administration</a><form action="/logout" method="post"><input type="hidden" name="_token" :value="csrf"><button><i aria-hidden="true" class="ti ti-logout"></i>Sign out</button></form></div></details></template>